/** Compact border controls. Selector label is 11sp; camera pictogram 14dp inside a 48dp row. */
public final class PhotoBorderPanel implements AutoCloseable {
    public interface Host {
        PhotoBorder border();PhotoCaptureInfo capture();boolean ready();String identity();Bitmap thumbnail();PresetPreviewProfile colour();
        void change(PhotoBorder border);void undo();void redo();boolean canUndo();boolean canRedo();void error(String message);
    }
    private static final int TEXT=0xfff4f5f7,MUTED=0xffbab1a7,ACCENT=0xfff3b493,FIELD=0xff292724;
    private final Activity activity;private final Host host;private final Handler main=new Handler(Looper.getMainLooper());
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile boolean closed;private volatile int request;private int tab;private String thumbKey="",lastSource="";private PhotoBorder lastBorder=PhotoBorder.NONE;
    private LinearLayout root,body,cards,modelRow;private final Button[] tabs=new Button[3];private final ImageView[] images=new ImageView[4];private final LinearLayout[] tiles=new LinearLayout[4];private final TextView[] labels=new TextView[4];private TextView model,badge;private Button undo,redo;private Dialog popup,fieldDialog;private boolean manualCamera;
    public PhotoBorderPanel(Activity a,Host h){activity=a;host=h;}
    public View create(){root=column();LinearLayout head=row();String[] names={"样式","信息","外观"};for(int i=0;i<3;i++){final int n=i;tabs[i]=button(names[i],()->{tab=n;rebuildBody();});head.addView(tabs[i],new LinearLayout.LayoutParams(0,dp(48),1));}undo=iconButton(AppIcon.Kind.UNDO,"撤销",host::undo);redo=iconButton(AppIcon.Kind.REDO,"重做",host::redo);head.addView(undo,new LinearLayout.LayoutParams(dp(48),dp(48)));head.addView(redo,new LinearLayout.LayoutParams(dp(48),dp(48)));root.addView(head);body=column();root.addView(body,new LinearLayout.LayoutParams(-1,dp(128)));rebuildBody();return root;}
    private void rebuildBody(){if(body==null)return;body.removeAllViews();cards=null;model=null;for(int i=0;i<3;i++){tabs[i].setTextColor(i==tab?ACCENT:MUTED);tabs[i].setSelected(i==tab);tabs[i].setBackground(underline(i==tab));}if(tab==0)styles();else if(tab==1)information();else appearance();refresh();}
    private void styles(){HorizontalScrollView scroll=new HorizontalScrollView(activity);scroll.setHorizontalScrollBarEnabled(false);cards=row();scroll.addView(cards);body.addView(scroll,new LinearLayout.LayoutParams(-1,dp(80)));for(int i=0;i<4;i++){final int t=i;LinearLayout tile=column();tile.setPadding(dp(4),dp(3),dp(4),0);tile.setGravity(Gravity.CENTER);ImageView preview=new ImageView(activity);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);tile.addView(preview,new LinearLayout.LayoutParams(-1,dp(50)));TextView label=text(PhotoBorder.TEMPLATES[i],10,MUTED);label.setGravity(Gravity.CENTER);label.setSingleLine(true);tile.addView(label,new LinearLayout.LayoutParams(-1,dp(22)));tile.setOnClickListener(v->{if(host.ready())host.change(host.border().withTemplate(t));});tile.setContentDescription(PhotoBorder.TEMPLATES[i]);tile.setFocusable(true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(84),dp(77));p.rightMargin=dp(8);cards.addView(tile,p);images[i]=preview;tiles[i]=tile;labels[i]=label;}
        modelRow=row();modelRow.setPadding(dp(10),0,dp(8),0);ImageView camera=icon(AppIcon.Kind.CAMERA,MUTED);modelRow.addView(camera,new LinearLayout.LayoutParams(dp(14),dp(14)));model=text("",11,MUTED);LinearLayout.LayoutParams textParams=new LinearLayout.LayoutParams(-2,-1);textParams.leftMargin=dp(10);modelRow.addView(model,textParams);badge=text("自动识别",9,ACCENT);badge.setPadding(dp(6),dp(2),dp(6),dp(2));GradientDrawable bd=shape(0x15f3b493,12);bd.setStroke(dp(1),0x50f3b493);badge.setBackground(bd);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-2,-2);bp.leftMargin=dp(8);modelRow.addView(badge,bp);Space spacer=new Space(activity);modelRow.addView(spacer,new LinearLayout.LayoutParams(0,1,1));ImageView arrow=icon(AppIcon.Kind.CHEVRON,MUTED);modelRow.addView(arrow,new LinearLayout.LayoutParams(dp(14),dp(14)));modelRow.setOnClickListener(v->showCamera());modelRow.setFocusable(true);modelRow.setBackground(new RippleDrawable(ColorStateList.valueOf(0x22f3b493),shape(Color.TRANSPARENT,0),null));body.addView(modelRow,new LinearLayout.LayoutParams(-1,dp(48)));thumbKey="";
    }
    public void refresh(){if(root==null)return;String source=host.identity();if(!source.equals(lastSource)||(tab!=0&&!host.border().equals(lastBorder))){lastSource=source;lastBorder=host.border();rebuildBody();return;}undo.setEnabled(host.ready()&&host.canUndo());redo.setEnabled(host.ready()&&host.canRedo());undo.setAlpha(undo.isEnabled()?1:.35f);redo.setAlpha(redo.isEnabled()?1:.35f);if(tab!=0)return;PhotoBorder b=host.border();for(int i=0;i<4;i++){boolean active=i==b.template;GradientDrawable bg=shape(Color.TRANSPARENT,8);if(active)bg.setStroke(dp(2),ACCENT);tiles[i].setBackground(bg);tiles[i].setSelected(active);tiles[i].setEnabled(host.ready());labels[i].setTextColor(active?ACCENT:MUTED);tiles[i].setContentDescription(PhotoBorder.TEMPLATES[i]+(active?"，已选择":""));}String name=PhotoCaptureInfo.friendly(host.capture().model(b));model.setText(name.isEmpty()?"选择机型":name);model.setMaxWidth(dp(160));model.setSingleLine(true);model.setEllipsize(TextUtils.TruncateAt.END);badge.setText(b.automatic?"自动识别":"手动选择");modelRow.setContentDescription("品牌与机型，"+(name.isEmpty()?"未识别":name)+"，"+badge.getText());modelRow.setEnabled(host.ready());requestThumbnails();}
    private void requestThumbnails(){Bitmap source=host.thumbnail();if(!host.ready()||source==null)return;PhotoBorder settings=host.border();PhotoCaptureInfo capture=host.capture();PresetPreviewProfile profile=host.colour();String key=System.identityHashCode(source)+":"+profile.modelVersion()+":"+settings.identity();if(key.equals(thumbKey))return;thumbKey=key;final int token=++request;worker.execute(()->{if(closed||token!=request)return;Bitmap colour=null;Bitmap[] outputs=new Bitmap[4];try{colour=PhotoFilterEditor.renderColour(source,profile);PhotoBorderRenderer renderer=new PhotoBorderRenderer(activity.getAssets());for(int i=0;i<4;i++){if(closed||token!=request)return;outputs[i]=renderer.apply(colour,settings.withTemplate(i),capture);}Bitmap[] result=outputs;main.post(()->{if(closed||token!=request||cards==null)return;for(int i=0;i<4;i++)images[i].setImageBitmap(result[i]);});}catch(Exception|OutOfMemoryError error){main.post(()->{if(!closed&&token==request)host.error(error.getMessage()==null?"边框预览暂不可用。":error.getMessage());});}});}
    private void information(){ScrollView scroll=new ScrollView(activity);LinearLayout list=column();String[] names={"机型","焦距","光圈","快门","ISO","拍摄时间"};PhotoBorder b=host.border();for(int i=0;i<names.length;i++){final int index=i;LinearLayout row=row();Button entry=button(names[i]+"  "+(i==0?host.capture().model(b):host.capture().field(b,i-1)),()->{if(index==0)showCamera();else editField(index-1,names[index]);});entry.setTextColor(TEXT);entry.setGravity(Gravity.CENTER_VERTICAL);entry.setSingleLine(true);entry.setEllipsize(TextUtils.TruncateAt.END);row.addView(entry,new LinearLayout.LayoutParams(0,dp(48),1));CheckBox show=new CheckBox(activity);show.setButtonTintList(ColorStateList.valueOf(ACCENT));show.setChecked(b.shows(i));show.setContentDescription("显示"+names[i]);show.setOnCheckedChangeListener((v,checked)->host.change(host.border().withVisible(index,checked)));row.addView(show,new LinearLayout.LayoutParams(dp(48),dp(48)));list.addView(row);}scroll.addView(list);body.addView(scroll,new LinearLayout.LayoutParams(-1,-1));}
    private void editField(int index,String name){if(!host.ready())return;PhotoBorder starting=host.border();final String identity=host.identity();EditText input=input(name+"，留空使用原图值");input.setText(starting.field(index));input.setSelectAllOnFocus(true);showFieldDialog(new AlertDialog.Builder(themed()).setTitle("边框"+name).setMessage("原图值："+(host.capture().field(starting.withField(index,""),index).isEmpty()?"未记录":host.capture().field(starting.withField(index,""),index))).setView(input).setNegativeButton("取消",null).setPositiveButton("应用",(d,w)->{if(host.ready()&&identity.equals(host.identity())&&starting.equals(host.border()))try{host.change(starting.withField(index,input.getText().toString()));rebuildBody();}catch(IllegalArgumentException invalid){host.error(invalid.getMessage());}}).create());}
    private void appearance(){ScrollView scroll=new ScrollView(activity);LinearLayout list=column();String[] names={"边距","圆角","阴影","背景模糊"};int[] values={host.border().margin,host.border().corner,host.border().shadow,host.border().blur};for(int i=0;i<4;i++){final int index=i,min=i==0?50:0,max=i==0?160:i==2?150:200;LinearLayout line=row();line.addView(text(names[i],12,TEXT),new LinearLayout.LayoutParams(dp(66),dp(48)));SeekBar seek=new SeekBar(activity);seek.setMax(max-min);seek.setProgress(values[i]-min);seek.setProgressTintList(ColorStateList.valueOf(ACCENT));seek.setThumbTintList(ColorStateList.valueOf(ACCENT));seek.setContentDescription(names[i]);line.addView(seek,new LinearLayout.LayoutParams(0,dp(48),1));TextView value=text(values[i]+"%",11,MUTED);value.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);line.addView(value,new LinearLayout.LayoutParams(dp(44),dp(48)));seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int v,boolean user){value.setText((v+min)+"%");}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){if(host.ready())host.change(host.border().withAppearance(index,s.getProgress()+min));}});list.addView(line);}Button logo=button("Logo · "+new String[]{"跟随模板","彩色","白色","黑色"}[host.border().logo],this::chooseLogo);list.addView(logo,new LinearLayout.LayoutParams(-1,dp(48)));list.addView(button("恢复模板默认设置",()->{host.change(host.border().reset());rebuildBody();}),new LinearLayout.LayoutParams(-1,dp(48)));scroll.addView(list);body.addView(scroll,new LinearLayout.LayoutParams(-1,-1));}
    public void showCamera(){if(!host.ready())return;manualCamera=!host.border().automatic;showCameraSheet();}
    private void showCameraSheet(){dismiss();final PhotoBorder starting=host.border();final String identity=host.identity();LinearLayout content=column();content.setPadding(dp(20),dp(8),dp(20),dp(16));content.setBackground(shape(0xff242321,22));LinearLayout title=row();TextView heading=text("品牌与机型",18,TEXT);heading.setTypeface(null,Typeface.BOLD);title.addView(heading,new LinearLayout.LayoutParams(0,dp(48),1));title.addView(iconButton(AppIcon.Kind.CLOSE,"关闭",this::dismiss),new LinearLayout.LayoutParams(dp(48),dp(48)));content.addView(title);LinearLayout modes=row();Button auto=button("自动识别",()->{manualCamera=false;showCameraSheet();}),manual=button("手动选择",()->{manualCamera=true;showCameraSheet();});auto.setBackground(shape(!manualCamera?0x40f3b493:FIELD,12));manual.setBackground(shape(manualCamera?0x40f3b493:FIELD,12));modes.addView(auto,new LinearLayout.LayoutParams(0,dp(48),1));modes.addView(manual,new LinearLayout.LayoutParams(0,dp(48),1));content.addView(modes);String detected=PhotoCaptureInfo.friendly(host.capture().model);TextView detectedLabel=text(detected.isEmpty()?"原图未记录机型，可手动选择":"已识别："+detected+" · 来自原始照片",12,MUTED);detectedLabel.setMaxLines(2);content.addView(detectedLabel,new LinearLayout.LayoutParams(-1,dp(48)));
        if(!manualCamera){content.addView(primaryButton("使用自动识别",()->{if(host.ready()&&identity.equals(host.identity())&&starting.equals(host.border()))host.change(starting.withCamera(true,"",""));dismiss();rebuildBody();}),new LinearLayout.LayoutParams(-1,dp(48)));show(content);return;}
        EditText search=input("搜索机型");content.addView(search,new LinearLayout.LayoutParams(-1,dp(48)));HorizontalScrollView chips=new HorizontalScrollView(activity);chips.setHorizontalScrollBarEnabled(false);LinearLayout brands=row();chips.addView(brands);content.addView(chips,new LinearLayout.LayoutParams(-1,dp(48)));String[] brandKeys={"NIKON","FUJIFILM","SONY","CANON"},brandLabels={"尼康","富士","索尼","佳能"};String initial=PhotoCaptureInfo.brandKey(host.capture().brand(starting));final String[] chosenBrand={Arrays.asList(brandKeys).contains(initial)?initial:"NIKON"},chosenModel={host.capture().model(starting)};ScrollView rowsScroll=new ScrollView(activity);LinearLayout rows=column();rowsScroll.addView(rows);content.addView(rowsScroll,new LinearLayout.LayoutParams(-1,0,1));final Runnable[] populate={null};populate[0]=()->{rows.removeAllViews();String query=search.getText().toString().trim().toLowerCase(Locale.ROOT);LinkedHashSet<String> models=new LinkedHashSet<>();if(chosenBrand[0].equals(host.capture().brand)&&!host.capture().model.isEmpty())models.add(host.capture().model);if(chosenBrand[0].equals(host.capture().brand(starting))&&!host.capture().model(starting).isEmpty())models.add(host.capture().model(starting));models.addAll(Arrays.asList(models(chosenBrand[0])));for(String m:models){if(!PhotoCaptureInfo.friendly(m).toLowerCase(Locale.ROOT).contains(query))continue;Button choice=button(PhotoCaptureInfo.friendly(m),()->{chosenModel[0]=m;populate[0].run();});choice.setTextColor(m.equals(chosenModel[0])?ACCENT:TEXT);if(m.equals(chosenModel[0]))choice.setCompoundDrawablesRelativeWithIntrinsicBounds(null,null,new AppIcon(AppIcon.Kind.CHECK,ACCENT,activity.getResources().getDisplayMetrics().density),null);choice.setGravity(Gravity.CENTER_VERTICAL);choice.setTextSize(14);rows.addView(choice,new LinearLayout.LayoutParams(-1,dp(48)));}for(int i=0;i<brands.getChildCount();i++)((Button)brands.getChildAt(i)).setTextColor(brandKeys[i].equals(chosenBrand[0])?ACCENT:MUTED);};for(int i=0;i<4;i++){final int n=i;brands.addView(button(brandLabels[i],()->{chosenBrand[0]=brandKeys[n];chosenModel[0]="";populate[0].run();}),new LinearLayout.LayoutParams(dp(72),dp(48)));}search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){populate[0].run();}});populate[0].run();content.addView(button("自定义机型",()->{EditText custom=input("输入机型，最多 96 个字符");custom.setText(chosenModel[0]);showFieldDialog(new AlertDialog.Builder(themed()).setTitle("自定义机型").setView(custom).setNegativeButton("取消",null).setPositiveButton("使用",(d,w)->{if(host.ready()&&identity.equals(host.identity())&&starting.equals(host.border()))try{host.change(starting.withCamera(false,chosenBrand[0],custom.getText().toString()));dismiss();rebuildBody();}catch(IllegalArgumentException invalid){host.error(invalid.getMessage());}}).create());}),new LinearLayout.LayoutParams(-1,dp(48)));content.addView(text("仅修改边框上的显示信息",11,MUTED),new LinearLayout.LayoutParams(-1,dp(28)));content.addView(primaryButton("使用所选机型",()->{if(chosenModel[0].isEmpty()){host.error("请先选择机型，或输入自定义机型。");return;}if(host.ready()&&identity.equals(host.identity())&&starting.equals(host.border()))host.change(starting.withCamera(false,chosenBrand[0],chosenModel[0]));dismiss();rebuildBody();}),new LinearLayout.LayoutParams(-1,dp(48)));show(content);
    }
    private static String[] models(String brand){switch(brand){case "NIKON":return new String[]{"NIKON Z 6_2","NIKON Z 6_3","NIKON Z f","NIKON Z 8","NIKON Z 9","NIKON Z 5","NIKON Z 7_2","NIKON Z 50","NIKON Z fc","NIKON D850","NIKON D750"};case "FUJIFILM":return new String[]{"X-T20","X-T30 II","X-T4","X-T5","X-S20","X100VI","X-H2","GFX100 II"};case "SONY":return new String[]{"ILCE-7M3","ILCE-7M4","ILCE-7RM5","ILCE-7CM2","ILCE-6700"};default:return new String[]{"Canon EOS R5","Canon EOS R6 Mark II","Canon EOS R8","Canon EOS R50"};}}
    private void show(LinearLayout content){Dialog d=new Dialog(activity);popup=d;d.requestWindowFeature(Window.FEATURE_NO_TITLE);boolean compact=activity.getResources().getConfiguration().screenHeightDp<520;if(compact&&manualCamera){for(int i=0;i<content.getChildCount();i++)if(content.getChildAt(i) instanceof ScrollView){content.getChildAt(i).setLayoutParams(new LinearLayout.LayoutParams(-1,dp(192)));}ScrollView scroll=new ScrollView(activity);scroll.addView(content);d.setContentView(scroll);}else d.setContentView(content);Window window=d.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setGravity(Gravity.BOTTOM);window.setDimAmount(.35f);window.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}d.show();if(window!=null)window.setLayout(-1,manualCamera?(int)(activity.getResources().getDisplayMetrics().heightPixels*(compact?.95:.76)):-2);d.setOnDismissListener(v->{if(popup==d)popup=null;});}
    public void invalidate(){request++;thumbKey="";dismiss();}
    public boolean dismiss(){boolean had=popup!=null||fieldDialog!=null;if(fieldDialog!=null){Dialog d=fieldDialog;fieldDialog=null;d.dismiss();}if(popup!=null){Dialog d=popup;popup=null;d.dismiss();}return had;}
    private void showFieldDialog(AlertDialog d){if(fieldDialog!=null)fieldDialog.dismiss();fieldDialog=d;d.setOnDismissListener(v->{if(fieldDialog==d)fieldDialog=null;});d.show();}
    private void chooseLogo(){if(!host.ready())return;final String identity=host.identity();final PhotoBorder starting=host.border();showFieldDialog(new AlertDialog.Builder(themed()).setTitle("Logo 样式").setSingleChoiceItems(new String[]{"跟随模板","彩色","白色","黑色"},starting.logo,(d,w)->{if(host.ready()&&identity.equals(host.identity())&&starting.equals(host.border()))host.change(starting.withLogo(w));d.dismiss();rebuildBody();}).setNegativeButton("取消",null).create());}
    private Context themed(){return new ContextThemeWrapper(activity,cc.huevia.R.style.AppThemeDark);}
    private EditText input(String hint){EditText e=new EditText(themed());e.setTextColor(TEXT);e.setHintTextColor(MUTED);e.setTextSize(14);e.setSingleLine(true);e.setHint(hint);e.setPadding(dp(12),0,dp(12),0);e.setBackground(shape(FIELD,12));e.setFilters(new InputFilter[]{new InputFilter.LengthFilter(96)});return e;}
    private LinearLayout column(){LinearLayout r=new LinearLayout(activity);r.setOrientation(1);return r;}private LinearLayout row(){LinearLayout r=new LinearLayout(activity);r.setGravity(Gravity.CENTER_VERTICAL);return r;}
    private TextView text(String s,int size,int color){TextView v=new TextView(activity);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setGravity(Gravity.CENTER_VERTICAL);v.setIncludeFontPadding(false);return v;}
    private Button button(String name,Runnable action){Button b=new Button(themed());b.setText(name);b.setAllCaps(false);b.setTextSize(13);b.setTextColor(ACCENT);b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(dp(48));b.setMinimumHeight(dp(48));b.setPadding(dp(8),0,dp(8),0);b.setBackground(new RippleDrawable(ColorStateList.valueOf(0x22f3b493),shape(Color.TRANSPARENT,12),null));b.setStateListAnimator(null);b.setOnClickListener(v->action.run());return b;}
    private Button primaryButton(String name,Runnable action){Button b=button(name,action);b.setBackground(shape(ACCENT,14));b.setTextColor(0xff352016);return b;}
    private Button iconButton(AppIcon.Kind kind,String name,Runnable action){Button b=button("",action);b.setCompoundDrawablesRelativeWithIntrinsicBounds(new AppIcon(kind,TEXT,activity.getResources().getDisplayMetrics().density),null,null,null);b.setPadding(dp(12),0,dp(12),0);b.setContentDescription(name);return b;}
    private ImageView icon(AppIcon.Kind kind,int color){ImageView i=new ImageView(activity);i.setImageDrawable(new AppIcon(kind,color,activity.getResources().getDisplayMetrics().density));i.setScaleType(ImageView.ScaleType.FIT_CENTER);return i;}
    private Drawable underline(boolean active){LayerDrawable d=new LayerDrawable(new Drawable[]{shape(Color.TRANSPARENT,0),shape(active?ACCENT:Color.TRANSPARENT,1)});d.setLayerSize(1,dp(18),dp(2));d.setLayerGravity(1,Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);d.setLayerInset(1,0,0,0,dp(5));return d;}
    private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private int dp(float n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
    @Override public void close(){closed=true;request++;dismiss();worker.shutdownNow();main.removeCallbacksAndMessages(null);}
}
